-- Menu labels (Raw), cutlet/gyoza choices, merged Spicy Maki, GF spicy mayo.
-- Clear the Supabase SQL editor, paste this ENTIRE file, then Run. Safe to re-run.
-- ASCII only. One statement per id where possible (avoids editor mid-list splits).

-- Prefer existing slug='raw' row if present (unique on slug, not only id).
INSERT INTO labels (id, name, slug) VALUES
  ('22222222-2222-2222-2222-222222222205'::uuid, 'Raw', 'raw')
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name;

-- Merge Spicy Maki (base $0 with absolute protein options)
UPDATE menu_items
SET name = 'SPICY MAKI',
    description = '6 pcs - Choose Salmon, Red Tuna, or Scallop',
    price = 0,
    is_available = true,
    has_roll_options = false
WHERE id = 'a1000001-0000-0000-0000-00000000000e'::uuid;

UPDATE menu_items SET is_available = false
WHERE id = 'a1000001-0000-0000-0000-00000000004b'::uuid;

UPDATE menu_items SET is_available = false
WHERE id = 'a1000001-0000-0000-0000-00000000005a'::uuid;

UPDATE menu_items
SET name = 'SPICY MAKI (GF)',
    description = '6 pcs - Choose Salmon, Red Tuna, or Scallop',
    price = 0,
    is_available = true,
    has_roll_options = false
WHERE id = 'a2000001-0000-0000-0000-000000000002'::uuid;

UPDATE menu_items SET is_available = false
WHERE id = 'a2000001-0000-0000-0000-00000000001c'::uuid;

UPDATE menu_items SET is_available = false
WHERE id = 'a2000001-0000-0000-0000-000000000031'::uuid;

INSERT INTO menu_options (id, name, price_modifier, sort_order) VALUES
  ('33333333-3333-3333-3333-333333333729'::uuid, 'Chicken', 0, 68),
  ('33333333-3333-3333-3333-333333333730'::uuid, 'Beef', 0, 69),
  ('33333333-3333-3333-3333-333333333755'::uuid, 'Salmon', 9, 75),
  ('33333333-3333-3333-3333-333333333756'::uuid, 'Red Tuna', 9.5, 76),
  ('33333333-3333-3333-3333-333333333757'::uuid, 'Scallop', 9.5, 77)
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  price_modifier = EXCLUDED.price_modifier,
  sort_order = EXCLUDED.sort_order;

-- Cutlet: pork + chicken
DELETE FROM menu_item_options
WHERE menu_item_id = 'a1000001-0000-0000-0000-000000000035'::uuid;

INSERT INTO menu_item_options (menu_item_id, menu_option_id) VALUES
  ('a1000001-0000-0000-0000-000000000035'::uuid, '33333333-3333-3333-3333-333333333725'::uuid),
  ('a1000001-0000-0000-0000-000000000035'::uuid, '33333333-3333-3333-3333-333333333729'::uuid)
ON CONFLICT DO NOTHING;

UPDATE menu_items
SET description = 'With spicy sauce. Choose pork or chicken'
WHERE id = 'a1000001-0000-0000-0000-000000000035'::uuid;

-- Gyoza: add beef
INSERT INTO menu_item_options (menu_item_id, menu_option_id) VALUES
  ('a1000001-0000-0000-0000-000000000036'::uuid, '33333333-3333-3333-3333-333333333730'::uuid)
ON CONFLICT DO NOTHING;

UPDATE menu_items
SET description = '5 pcs - Choose pork, beef, or veggie'
WHERE id = 'a1000001-0000-0000-0000-000000000036'::uuid;

-- Spicy maki options (regular + GF)
DELETE FROM menu_item_options
WHERE menu_item_id IN (
  'a1000001-0000-0000-0000-00000000000e'::uuid,
  'a2000001-0000-0000-0000-000000000002'::uuid
)
AND menu_option_id IN (
  SELECT id FROM menu_options WHERE name IN ('Deep-fried', 'Replace with Soy Sheet', 'Spicy')
);

